package com.google.gson.stream;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class JsonWriter_value_TriageGen2Test {

    private JsonWriter jsonWriter;
    private Writer mockWriter;

    @Before
    public void setUp() {
        mockWriter = mock(Writer.class);
        jsonWriter = new JsonWriter(mockWriter);
    }

    @Test
    public void testValuePositiveLong() throws IOException {
        long value = 123456789L;
        jsonWriter.value(value);
        verify(mockWriter, times(1)).write(eq("123456789"));
    }

    @Test
    public void testValueNegativeLong() throws IOException {
        long value = -987654321L;
        jsonWriter.value(value);
        verify(mockWriter, times(1)).write(eq("-987654321"));
    }

    @Test
    public void testValueZeroLong() throws IOException {
        long value = 0L;
        jsonWriter.value(value);
        verify(mockWriter, times(1)).write(eq("0"));
    }

    @Test
    public void testValueMaxLong() throws IOException {
        long value = Long.MAX_VALUE;
        jsonWriter.value(value);
        verify(mockWriter, times(1)).write(eq("9223372036854775807"));
    }

    @Test
    public void testValueMinLong() throws IOException {
        long value = Long.MIN_VALUE;
        jsonWriter.value(value);
        verify(mockWriter, times(1)).write(eq("-9223372036854775808"));
    }

    @Test(expected = IOException.class)
    public void testValueThrowsIOException() throws IOException {
        Writer writer = mock(Writer.class);
        when(writer.write(anyString())).thenThrow(new IOException());
        JsonWriter jsonWriter = new JsonWriter(writer);
        jsonWriter.value(123L);
    }
}
